import{_ as a,o as e,c as s,a0 as r}from"./chunks/framework.DQOulFGV.js";const b=JSON.parse('{"title":"把 Mac 备份到 Backblaze B2","description":"用 Keelhaven 把 Mac 加密、定时备份到你自己的 Backblaze B2 存储桶：建桶、建应用密钥、要填的五个字段，以及 B2 必须设的那条生命周期规则。","frontmatter":{"title":"把 Mac 备份到 Backblaze B2","description":"用 Keelhaven 把 Mac 加密、定时备份到你自己的 Backblaze B2 存储桶：建桶、建应用密钥、要填的五个字段，以及 B2 必须设的那条生命周期规则。"},"headers":[],"relativePath":"zh/guides/backblaze-b2.md","filePath":"zh/guides/backblaze-b2.md"}'),o={name:"zh/guides/backblaze-b2.md"};function n(l,t,i,d,c,h){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="把-mac-备份到-backblaze-b2" tabindex="-1">把 Mac 备份到 Backblaze B2 <a class="header-anchor" href="#把-mac-备份到-backblaze-b2" aria-label="Permalink to &quot;把 Mac 备份到 Backblaze B2&quot;">​</a></h1><p>Keelhaven 先在你的 Mac 上把选中的文件夹加密，再传到属于你的 B2 存储桶。 Backblaze 存的是它读不了的数据，中间也没有 Keelhaven 的服务器。</p><p>全程大约十分钟，大部分花在 Backblaze 那边。</p><h2 id="_1-建一个存储桶" tabindex="-1">1. 建一个存储桶 <a class="header-anchor" href="#_1-建一个存储桶" aria-label="Permalink to &quot;1. 建一个存储桶&quot;">​</a></h2><p>在 Backblaze 网页控制台打开 <strong>Buckets</strong>，点 <strong>Create a Bucket</strong>。</p><ul><li><strong>Files in Bucket are：</strong> 选 Private。</li><li><strong>Object Lock：</strong> 保持关闭。开了之后旧备份就永远删不掉。</li><li><strong>Default Encryption：</strong> 开不开都行。数据离开 Mac 之前已经加密过了。</li></ul><p>建好后，存储桶上会显示一个 <strong>Endpoint</strong>，形如 <code>s3.us-west-004.backblazeb2.com</code>。第 4 步要用。</p><h2 id="_2-设置生命周期规则" tabindex="-1">2. 设置生命周期规则 <a class="header-anchor" href="#_2-设置生命周期规则" aria-label="Permalink to &quot;2. 设置生命周期规则&quot;">​</a></h2><p>在这个存储桶上打开 <strong>Lifecycle Settings</strong>，选 <strong>Keep only the last version of the file</strong>。</p><p>备份工具删掉的东西，B2 并不真删，而是隐藏起来继续计费。设了这一项，旧备份 才会真正从账单里消失。详细原因见<a href="/zh/#faq">常见问题</a>。</p><h2 id="_3-建一个应用密钥" tabindex="-1">3. 建一个应用密钥 <a class="header-anchor" href="#_3-建一个应用密钥" aria-label="Permalink to &quot;3. 建一个应用密钥&quot;">​</a></h2><p>打开 <strong>Application Keys</strong>，点 <strong>Add a New Application Key</strong>。</p><ul><li><strong>Allow access to Bucket(s)：</strong> 选刚建的那个存储桶。</li><li><strong>Type of Access：</strong> Read and Write。</li><li><strong>Allow List All Bucket Names：</strong> 勾上。只限单个存储桶的密钥走 S3 接口时， Backblaze 要求打开它。</li></ul><p>之后会显示一个 <strong>keyID</strong> 和一个 <strong>applicationKey</strong>。applicationKey 只显示 这一次，两个都马上复制下来。</p><p>页面顶部的 master application key 用不了：B2 的 S3 接口只认这样新建的密钥。</p><h2 id="_4-接入-keelhaven" tabindex="-1">4. 接入 Keelhaven <a class="header-anchor" href="#_4-接入-keelhaven" aria-label="Permalink to &quot;4. 接入 Keelhaven&quot;">​</a></h2><p>点菜单栏里的灯塔图标，选<strong>添加备份计划…</strong>，挑好文件夹。到下一步，展开 <strong>高级选项</strong>，选 <strong>S3 兼容存储</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>服务地址</td><td>第 1 步的 Endpoint</td></tr><tr><td>存储桶</td><td>存储桶的名字</td></tr><tr><td>路径前缀</td><td>可不填。桶里的一个子目录，比如 <code>macbook</code></td></tr><tr><td>Access Key ID</td><td>keyID</td></tr><tr><td>Secret Access Key</td><td>applicationKey</td></tr></tbody></table><p>然后设一个加密密码，或者让 Keelhaven 自动生成。密码存在钥匙串里，最好也 存一份进密码管理器。没有它，谁都读不了这份备份，包括你自己。</p><h2 id="_5-选备份频率" tabindex="-1">5. 选备份频率 <a class="header-anchor" href="#_5-选备份频率" aria-label="Permalink to &quot;5. 选备份频率&quot;">​</a></h2><p>每小时、每天或每周。第一次备份会上传全部内容，之后每次只传有变化的部分。</p><h2 id="值得知道" tabindex="-1">值得知道 <a class="header-anchor" href="#值得知道" aria-label="Permalink to &quot;值得知道&quot;">​</a></h2><p><strong>第一次上传可以限速。</strong> 最后一步的<strong>自定义这个计划</strong>里有上传限速，之后在 <strong>编辑计划 → 高级</strong>里也能改，免得首次备份占满你的网络。</p><p><strong>不设置的话，备份会一直增长。</strong> 删不删你的数据，Keelhaven 从不替你做主， 所以保留策略默认是关的。要开，去<strong>编辑计划 → 保留策略</strong>。</p><p><strong>不装 Keelhaven 也能恢复。</strong> 存储桶里是标准的 <a href="https://restic.net" target="_blank" rel="noreferrer">restic</a> 仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3:https://s3.us-west-004.backblazeb2.com/your-bucket</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span></code></pre></div><h2 id="换一家-s3-服务" tabindex="-1">换一家 S3 服务 <a class="header-anchor" href="#换一家-s3-服务" aria-label="Permalink to &quot;换一家 S3 服务&quot;">​</a></h2><p>五个字段在哪家都一样，只有服务地址不同。第 2 步的生命周期规则只是 B2 的事。</p><table tabindex="0"><thead><tr><th>服务商</th><th>服务地址</th></tr></thead><tbody><tr><td>Amazon S3</td><td><code>s3.amazonaws.com</code></td></tr><tr><td>Cloudflare R2</td><td><code>&lt;account-id&gt;.r2.cloudflarestorage.com</code></td></tr><tr><td>Wasabi</td><td><code>s3.&lt;region&gt;.wasabisys.com</code></td></tr><tr><td>MinIO 或其他自建服务</td><td><code>https://your-host:9000</code></td></tr></tbody></table>',29)])])}const g=a(o,[["render",n]]);export{b as __pageData,g as default};
